export const BIBLIOTECA_ERROR__LIBRO_NO_EXISTE = 0x1773; // 6003
/** LibroConPrestamos: Error, el libro tiene prestamos activos */
export const BIBLIOTECA_ERROR__LIBRO_CON_PRESTAMOS = 0x1774; // 6004

export type BibliotecaError =
  | typeof BIBLIOTECA_ERROR__LIBRO_CON_PRESTAMOS
  | typeof BIBLIOTECA_ERROR__LIBRO_NO_EXISTE
  | typeof BIBLIOTECA_ERROR__LIMITE_ALCANZADO
